(()=>{"use strict";
const KEY="vesper-selfedu-v1", OLD="batlab-local-v2";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const now=()=>new Date().toISOString();
const domains=[
{id:"math",icon:"∑",name:"Mathematics",desc:"Structures, proof, quantity and change.",topics:["functions","limits","derivatives"]},
{id:"physics",icon:"◉",name:"Physics",desc:"Matter, energy, fields and the laws of nature.",topics:["motion","forces","waves"]},
{id:"chem",icon:"⚗",name:"Chemistry",desc:"Atoms, bonds, reactions and materials.",topics:["atoms","bonding","reactions"]},
{id:"bio",icon:"⌬",name:"Biology",desc:"Living systems, information and evolution.",topics:["cells","genetics","evolution"]},
{id:"cs",icon:"⌘",name:"Computer science",desc:"Computation, algorithms and information.",topics:["logic","algorithms","data"]},
{id:"eng",icon:"⚙",name:"Engineering",desc:"Designed systems, constraints and applied science.",topics:["systems","circuits","materials"]}
];
const topics={
functions:["Functions and representations","math","A function assigns one output to each allowed input.","A function is a rule connecting inputs and outputs. For f(x) = 2x + 3, input 4 produces 11. A graph shows all input-output pairs together.","f(x) = 2x + 3","For f(x) = 3x − 2, find f(4).",["10"],"Substitute 4 for x: 3 × 4 − 2."],
limits:["Limits and approaching values","math","A limit describes the value a function approaches as its input approaches a point.","Imagine moving along a curve towards x = 2. The function's value may approach 5 even if the point itself is missing. A limit asks what the outputs approach.","lim x→2 (x + 3) = 5","As x approaches 3, what does x + 4 approach?",["7"],"For a continuous linear function, substitute 3."],
derivatives:["Derivatives and instantaneous change","math","A derivative measures instantaneous rate of change.","Average rate of change is the slope between two points. Shrink the interval towards zero and the secant slope approaches the tangent slope. The derivative is this limiting slope.","f′(x) = lim h→0 [f(x+h) − f(x)] / h","If f(x) = x², find f′(3).",["6"],"The derivative of x² is 2x. Evaluate at 3."],
motion:["Describing motion","physics","Motion describes how position changes over time.","Position tells where an object is. Displacement compares two positions. Velocity is the rate of change of displacement; acceleration is the rate of change of velocity. Direction matters: velocity is a vector.","average speed = distance / time","A runner moves 60 m in 10 s. Find average speed in m/s.",["6"],"Divide distance by elapsed time."],
forces:["Forces and Newton's laws","physics","A net force changes an object's momentum. For constant mass, F = ma.","Forces are interactions. Add external forces as vectors to find net force. A non-zero net force produces acceleration in the direction of that force.","ΣF = ma","A net force of 15 N acts on a 3 kg object. Find acceleration in m/s².",["5"],"Rearrange to a = F/m."],
waves:["Waves and energy transfer","physics","Waves transfer energy and information through oscillations.","A travelling wave has wavelength, frequency and speed. Frequency counts cycles per second; wavelength is the distance between matching points in adjacent cycles.","v = fλ","A wave has frequency 5 Hz and wavelength 2 m. Find speed in m/s.",["10"],"Multiply frequency by wavelength."],
atoms:["Atomic structure","chem","Atoms contain a nucleus of protons and neutrons, surrounded by electrons.","The number of protons defines the element. Neutrons change the isotope. Electrons determine charge and are central to chemical bonding. Quantum models describe electron probability distributions.","atomic number = number of protons","An atom has 8 protons. Which element is it?",["oxygen","o"],"Atomic number 8 identifies oxygen."],
bonding:["Chemical bonding","chem","Chemical bonds arise from electrostatic interactions involving electrons and nuclei.","Ionic bonding involves attraction between oppositely charged ions. Covalent bonding involves shared electron density. Metallic bonding involves delocalised electrons. Real bonds can have mixed character.","bonding = electron distribution + attraction","What type of bond involves a shared pair of electrons?",["covalent"],"Think of two atoms sharing electron density."],
reactions:["Chemical reactions","chem","Chemical reactions rearrange atoms and bonds; they do not create or destroy atoms.","Reactants become products through bond breaking and formation. Balance equations by changing coefficients, never subscripts. Each type of atom must be conserved.","reactants → products · atoms conserved","How many oxygen atoms are in 2H₂O?",["2","two"],"Each water molecule has one oxygen atom."],
cells:["Cell structure and function","bio","Cells are the basic structural and functional units of living organisms.","The cell membrane controls exchange with the environment. Cytoplasm hosts many reactions. Eukaryotic cells contain membrane-bound organelles; prokaryotic cells do not have a membrane-bound nucleus.","structure → function → system","Which organelle contains most of a eukaryotic cell's DNA?",["nucleus"],"It is the membrane-bound compartment that stores chromosomes."],
genetics:["Genes and inheritance","bio","Genes are DNA sequences whose variation and expression contribute to inherited traits.","DNA stores information in nucleotide sequences. Genes can be transcribed into RNA; many are translated into proteins. Inheritance depends on alleles, gene interactions and environment.","DNA → RNA → protein","What molecule carries hereditary information in most organisms?",["dna"],"It is the double-stranded molecule made of nucleotides."],
evolution:["Evolution by natural selection","bio","Evolution is change in heritable characteristics of populations across generations.","Natural selection occurs when heritable variation affects survival or reproductive success. Populations evolve; individuals do not evolve genetically during their lifetimes. Selection is not goal-directed.","variation + differential reproduction → population change","Does an individual organism evolve genetically during its lifetime?",["no"],"Evolution by natural selection describes population change across generations."],
logic:["Logic and formal reasoning","cs","Logic studies valid inference and the structure of propositions.","A proposition is true or false. An implication P → Q is false only when P is true and Q is false. Valid reasoning preserves truth from premises to conclusion.","P → Q ≡ ¬P ∨ Q","If P is true and Q is false, is P → Q true or false?",["false"],"An implication fails in the true-premise, false-conclusion case."],
algorithms:["Algorithms and complexity","cs","An algorithm is a finite, well-defined procedure for solving a class of problems.","Correctness asks whether an algorithm returns the right result for every valid input. Complexity describes how resource use grows with input size. Big-O is an asymptotic bound, not a stopwatch reading.","linear search O(n) · binary search O(log n)","If input size doubles, how many times more steps does linear work need?",["2","twice"],"Linear work grows in direct proportion to input size."],
data:["Data and representation","cs","Computers represent information using discrete states and formal encodings.","Binary uses two symbols, 0 and 1. A bit is one binary digit. Groups of bits encode numbers, text, images and instructions under agreed conventions. Representation is not the same as meaning.","8 bits = 1 byte","How many bits are in one byte?",["8","eight"],"A byte is conventionally a group of eight bits."],
systems:["Systems thinking","eng","An engineered system combines components, interactions and constraints to deliver a function.","A system has a boundary, inputs, outputs and internal interactions. Feedback can stabilise or destabilise behaviour. Engineers model the whole system because local improvements can create global problems.","inputs → system → outputs","What is output information fed back to influence future behaviour called?",["feedback"],"It is the return of information about system behaviour."],
circuits:["Electrical circuits","eng","An electric circuit is a connected path through which charge can move.","For an ideal resistor, Ohm's law relates voltage, current and resistance. In a simple series circuit, current is the same through each component.","V = IR","A 12 V source is connected across a 4 Ω resistor. Find current in amperes.",["3"],"Rearrange Ohm's law: I = V/R."],
materials:["Materials and properties","eng","Material behaviour emerges from composition, structure, processing and environment.","Strength, stiffness, toughness and hardness are different properties. A material can be stiff but brittle, or ductile but relatively soft. Selection depends on load, environment, cost and failure consequences.","structure + processing → properties → performance","Which property describes energy absorption before fracture?",["toughness"],"It is not the same as hardness or stiffness."]
};
const prereq={limits:["functions"],derivatives:["limits"],forces:["motion"],waves:["motion"],bonding:["atoms"],reactions:["bonding"],genetics:["cells"],evolution:["genetics"],algorithms:["logic"],data:["algorithms"],circuits:["systems"],materials:["systems"]};
const base={profile:{name:"",interests:[],goal:"Explore a question deeply"},questions:[],plans:[],resources:[],investigations:[],projects:[],notes:[],sessions:[],checks:[],recall:[],methodChecks:[],settings:{reducedMotion:false,compact:false},onboarded:false,lastView:"home"};
function normalizeState(raw){let x=Object.assign(structuredClone(base),raw||{});x.profile=Object.assign({},base.profile,raw?.profile||{});x.settings=Object.assign({},base.settings,raw?.settings||{});["questions","plans","resources","investigations","projects","notes","sessions","checks","recall","methodChecks"].forEach(k=>{if(!Array.isArray(x[k]))x[k]=[]});return x}
function load(){try{let x=JSON.parse(localStorage.getItem(KEY)||"null");if(x)return normalizeState(x)}catch{}try{let old=JSON.parse(localStorage.getItem(OLD)||"null");if(old){let x=structuredClone(base);x.profile.name=old.name||"";x.onboarded=!!old.onboarded;x.notes=(old.notes||[]).map(n=>({id:uid(),title:n.title,body:n.body,created:n.date||now(),tags:[]}));Object.keys(old.tries||{}).forEach(k=>x.checks.push({id:uid(),topic:k,correct:!!(old.done||{})[k],at:now(),kind:"legacy task check"}));return normalizeState(x)}}catch{}return structuredClone(base)}
let state=load(), currentQuestion=null, currentTopic=null, editingQuestionId=null;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){if($("#toast"))toast("Browser storage is full or unavailable. Export your work and free space.");return false}};
const path=()=>location.hash.replace(/^#\/?/,"").split("/").filter(Boolean);
const go=(p)=>{location.hash="/"+p};
const domain=id=>domains.find(d=>d.id===id);
const topicStatus=id=>{let a=state.checks.filter(c=>c.topic===id);return a.some(c=>c.correct)?"TASK EVIDENCE":a.length?"ATTEMPTED":"NOT ASSESSED"};
const allText=id=>topics[id].join(" ").toLowerCase();
function shell(view,body){let groups=[["START",["home","Start here"],["questions","My questions"],["discover","Explore fields"]],["LEARN",["pathways","Learning plans"],["study","Study desk"],["map","Knowledge map"],["method","Learn how to learn"]],["INVESTIGATE",["investigate","Investigation lab"],["models","Model bench"],["workshop","Creation workshop"],["journal","Field journal"],["resources","Resource library"]],["REFLECT",["recall","Recall practice"],["evidence","Capability evidence"]],["SYSTEM",["settings","Settings"]]];let nav=groups.map(g=>'<div class="nav-group"><small>'+g[0]+'</small>'+g.slice(1).map(item=>'<a href="#/'+item[0]+'" class="'+(view===item[0]?"active":"")+'"><span class="nav-mark">'+mark(item[0])+'</span>'+item[1]+'</a>').join("")+'</div>').join("");return '<aside class="sidebar" id="sidebar"><a class="brand" href="#/home"><span class="brand-mark">V</span><span><b>VESPER</b><small>SELF-EDUCATION SYSTEM</small></span></a><div class="nav-scroll">'+nav+'</div><div class="side-bottom"><div class="privacy-dot"></div><span>PRIVATE · THIS DEVICE</span></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" id="menu" aria-label="Open navigation">☰</button><div class="crumb">VESPER <span>/</span> '+esc(view.replace(/-/g," "))+'</div><div class="top-actions"><span class="profile-chip">'+esc(state.profile.name||"Independent learner")+'</span><a class="top-link" href="#/questions">+ New question</a></div></header><div class="content">'+body+'</div></main><div id="toast" role="status" aria-live="polite"></div>'}
function mark(v){return ({home:"⌂",questions:"?",discover:"⌕",pathways:"↗",study:"▤",map:"⌘",method:"∴",investigate:"⌁",models:"⌗",workshop:"◇",journal:"✎",resources:"▧",recall:"↻",evidence:"◎",settings:"⚙"})[v]||"·"}
function head(kicker,title,desc,action){return '<div class="page-head"><div><div class="eyebrow">'+kicker+'</div><h1>'+title+'</h1><p>'+desc+'</p></div>'+(action||"")+'</div>'}
function card(title,desc,meta,href,icon){return '<a class="feature-card" href="#/'+href+'"><div class="feature-icon">'+(icon||"↗")+'</div><div class="feature-meta">'+meta+'</div><h3>'+title+'</h3><p>'+desc+'</p><span class="card-arrow">Open workspace →</span></a>'}
function empty(title,desc,action,label){return '<div class="empty-state"><div class="empty-symbol">◇</div><h3>'+title+'</h3><p>'+desc+'</p>'+(action?'<a class="button primary" href="#/'+action+'">'+(label||"Get started")+'</a>':"")+'</div>'}
function countLabel(n,s){return n+" "+s+(n===1?"":"s")}
function home(){let q=state.questions.length,p=state.plans.length,i=state.investigations.length,pr=state.projects.length;let recent=state.questions.slice().reverse().slice(0,3);return '<section class="welcome-panel"><div class="welcome-copy"><div class="eyebrow">AN ENVIRONMENT FOR INDEPENDENT THINKING</div><h1>Start with what<br><em>you want to understand.</em></h1><p>VESPER helps you turn a question into a learning route, investigate it with evidence, and make something that demonstrates what you have learned.</p><div class="welcome-actions"><a class="button primary" href="#/questions">Develop a question <span>→</span></a><a class="button secondary" href="#/discover">Explore fields</a></div></div><div class="welcome-diagram"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit-core">V</div><span class="orbit-label l1">QUESTION</span><span class="orbit-label l2">KNOWLEDGE</span><span class="orbit-label l3">EVIDENCE</span></div></section><div class="section-row"><div><div class="eyebrow">YOUR WORKSPACE</div><h2>Intellectual work in progress</h2></div><span class="quiet-label">LOCAL · PRIVATE</span></div><div class="metric-grid"><div class="metric"><b>'+q+'</b><span>Questions developed</span></div><div class="metric"><b>'+p+'</b><span>Learning plans</span></div><div class="metric"><b>'+i+'</b><span>Investigations</span></div><div class="metric"><b>'+pr+'</b><span>Projects created</span></div></div><div class="section-row"><div><div class="eyebrow">CHOOSE YOUR NEXT MOVE</div><h2>Six connected workspaces</h2></div></div><div class="feature-grid">'+card("Develop a question","Turn an interest into a specific, investigable question.","CURIOSITY ENGINE","questions","?")+card("Build a learning plan","Map the knowledge, prerequisites and resources you need.","KNOWLEDGE ARCHITECT","pathways","↗")+card("Study a concept","Work through explanations, examples and independent checks.","LEARNING STUDIO","study","▤")+card("Investigate a claim","Form a hypothesis, define variables and record observations.","INVESTIGATION LAB","investigate","⌁")+card("Make something","Turn learning into a model, paper, experiment or working artefact.","CREATION WORKSHOP","workshop","◇")+card("Review your capability","Inspect evidence, uncertainty and what remains to be learned.","KNOWLEDGE INTELLIGENCE","evidence","◎")+'</div><div class="section-row"><div><div class="eyebrow">RECENT QUESTIONS</div><h2>Your lines of inquiry</h2></div><a class="text-link" href="#/questions">All questions →</a></div>'+(recent.length?'<div class="list-card">'+recent.map(q=>'<a class="list-row" href="#/question/'+q.id+'"><span class="row-mark">?</span><span class="row-main"><b>'+esc(q.title)+'</b><small>'+esc(q.field||"Interdisciplinary")+' · '+new Date(q.created).toLocaleDateString()+'</small></span><span class="row-arrow">→</span></a>').join("")+'</div>':empty("Nothing to organize yet","Start with a question you genuinely want to understand.","questions","Develop your first question"))}
function questions(){return head("CURIOSITY ENGINE","Your questions","A self-directed education begins with a question, not a course.","<a class='button primary' href='#/questions/new'>+ Develop question</a>")+(state.questions.length?'<div class="question-grid">'+state.questions.slice().reverse().map(q=>'<a class="question-card" href="#/question/'+q.id+'"><div class="feature-meta">'+esc(q.field||"OPEN INQUIRY")+' · '+esc(q.status||"Exploring")+'</div><h3>'+esc(q.title)+'</h3><p>'+esc(q.why||"No context added yet.")+'</p><div class="question-foot"><span>'+new Date(q.created).toLocaleDateString()+'</span><span>Open inquiry →</span></div></a>').join("")+'</div>':empty("What have you been wondering about?","Capture a question. VESPER will help refine it into a tractable investigation and learning plan.","questions/new","Develop a question"))}
function questionForm(q){let editing=!!q;return head("CURIOSITY ENGINE",editing?"Refine your question":"What do you want to understand?","Start in your own words. You do not need to know the terminology yet.")+'<form class="workspace-form" id="questionForm"><label>YOUR QUESTION<textarea name="title" required rows="3" placeholder="Why do binary black holes merge, and what determines the gravitational waves they emit?">'+esc(q?.title||"")+'</textarea></label><div class="form-grid"><label>FIELD<select name="field"><option>Physics</option><option>Mathematics</option><option>Computer science</option><option>Biology</option><option>Chemistry</option><option>Engineering</option><option>Interdisciplinary</option><option>Other</option></select></label><label>YOUR CURRENT LEVEL<select name="level"><option>New to this subject</option><option>Some foundations</option><option>Comfortable with the basics</option><option>Advanced study</option><option>Unsure</option></select></label></div><label>WHY DOES THIS INTEREST YOU?<textarea name="why" rows="2" placeholder="What sparked the question? What do you hope to understand?">'+esc(q?.why||"")+'</textarea></label><label>WHAT DO YOU ALREADY KNOW?<textarea name="known" rows="2" placeholder="List ideas, terms, or assumptions you already have. It is fine to leave this blank.">'+esc(q?.known||"")+'</textarea></label><label>WHAT WOULD A USEFUL OUTCOME LOOK LIKE?<textarea name="outcome" rows="2" placeholder="For example: explain the mechanism, reproduce a result, build a simulation, or write a research review.">'+esc(q?.outcome||"")+'</textarea></label><div class="form-actions"><button class="button primary" type="submit">'+(editing?"Save changes":"Create inquiry")+' →</button><a class="button secondary" href="#/questions">Cancel</a></div></form>'}
function questionDetail(id){let q=state.questions.find(x=>x.id===id);if(!q)return empty("Question not found","Return to your inquiry list.","questions","Your questions");let plan=state.plans.find(p=>p.questionId===id);return head("INQUIRY / "+esc(q.field||"OPEN"),esc(q.title),"A learner-owned question. You control its direction and depth.","<a class='button primary' href='#/pathways/new/"+id+"'>Build learning plan →</a>")+'<div class="detail-grid"><section class="paper-panel"><div class="eyebrow">WHY THIS MATTERS TO YOU</div><p>'+esc(q.why||"Not recorded.")+'</p><div class="eyebrow">WHAT YOU ALREADY KNOW</div><p>'+esc(q.known||"Not recorded.")+'</p><div class="eyebrow">DESIRED OUTCOME</div><p>'+esc(q.outcome||"Not defined yet.")+'</p><div class="form-actions"><button class="button secondary" data-edit-question="'+id+'">Edit inquiry</button><button class="button danger" data-delete-question="'+id+'">Delete</button></div></section><aside class="side-panel"><div class="eyebrow">CURRENT STATE</div><h3>'+esc(q.status||"Exploring")+'</h3><p>Created '+new Date(q.created).toLocaleDateString()+'</p>'+(plan?'<a class="button primary full" href="#/plan/'+plan.id+'">Open learning plan →</a>':'<a class="button primary full" href="#/pathways/new/'+id+'">Construct learning plan →</a>')+'<a class="button secondary full" href="#/investigate/new/'+id+'">Start investigation</a></aside></div>'}
function discover(){return head("OPEN DISCOVERY","Explore fields","Browse the landscape of STEM. Follow connections; do not treat these starter topics as a complete curriculum.")+'<div class="domain-grid">'+domains.map(d=>'<a class="domain-card" href="#/field/'+d.id+'"><span class="domain-icon">'+d.icon+'</span><div class="feature-meta">FIELD OF STUDY</div><h3>'+d.name+'</h3><p>'+d.desc+'</p><span class="card-arrow">'+d.topics.length+' starter concepts · Explore →</span></a>').join("")+'</div><div class="section-row"><div><div class="eyebrow">SEARCH THE STARTER LIBRARY</div><h2>Find a concept</h2></div></div><input id="topicSearch" class="search-input" placeholder="Search concepts, definitions or fields…"><div id="topicResults" class="topic-grid">'+topicCards(Object.keys(topics))+'</div><p class="footnote">The current library contains 18 authored starter concepts. It is a starting index, not a comprehensive or peer-reviewed STEM curriculum.</p>'}
function topicCards(ids){return ids.map(id=>{let t=topics[id];return '<a class="topic-card" href="#/study/'+id+'"><div class="feature-meta">'+domain(t[1]).name.toUpperCase()+' · '+topicStatus(id)+'</div><h3>'+t[0]+'</h3><p>'+t[2]+'</p><span>Study concept →</span></a>'}).join("")}
function fieldPage(id){let d=domain(id);if(!d)return empty("Field not found","Browse the available STEM fields.","discover","Explore fields");return head(d.name.toUpperCase(),"Explore "+d.name,d.desc)+'<div class="topic-grid">'+topicCards(d.topics)+'</div><div class="callout-note">These are entry points, not a prescribed sequence. Use the Knowledge Map to inspect the stated prerequisite relationships.</div>'}
const topicTerms={functions:["function","mapping","input","output","equation","mathematical model"],limits:["limit","calculus","approach","continuity"],derivatives:["derivative","differential","rate of change","calculus","optimization"],motion:["motion","orbit","orbital","trajectory","velocity","acceleration","mechanics","binary star","black hole"],forces:["force","gravity","gravitational","newton","mechanics","mass","black hole","orbit"],waves:["wave","gravitational wave","frequency","oscillation","radiation","signal","black hole merger"],atoms:["atom","atomic","element","electron","proton","neutron"],bonding:["bond","ionic","covalent","molecule","chemical"],reactions:["reaction","reactant","product","stoichiometry"],cells:["cell","organism","organelle","biology"],genetics:["gene","genetic","dna","inheritance","allele"],evolution:["evolution","selection","adaptation","population"],logic:["logic","proof","reasoning","proposition"],algorithms:["algorithm","complexity","neural network","machine learning","computation","model training"],data:["data","binary","information","encoding","dataset"],systems:["system","feedback","engineering","control","architecture"],circuits:["circuit","voltage","current","resistance","electric"],materials:["material","strength","stiffness","toughness","structure"]};
function suggestedTopics(qid){let q=state.questions.find(x=>x.id===qid);if(!q)return[];let text=[q.title,q.why,q.known,q.outcome,q.field].join(" ").toLowerCase(),scores=[];Object.keys(topics).forEach(k=>{let score=(topicTerms[k]||[]).reduce((n,term)=>n+(text.includes(term)?(term.includes(" ")?3:1):0),0);if(score)scores.push({id:k,score})});scores.sort((a,b)=>b.score-a.score);let picked=scores.slice(0,4).map(x=>x.id);if(!picked.length){let d=domains.find(x=>x.name.toLowerCase()===String(q.field||"").toLowerCase());picked=d?d.topics.slice(0,2):[]}let add=id=>{(prereq[id]||[]).forEach(p=>{if(!picked.includes(p)){picked.push(p);add(p)}})};picked.slice().forEach(add);return picked}
function coverageCaveat(qid){let q=state.questions.find(x=>x.id===qid);if(!q)return"";let t=[q.title,q.why,q.outcome].join(" ").toLowerCase(),gaps=[];if(/black hole|gravitational wave|general relativit|binary star|neutron star/.test(t))gaps.push("The starter library does not yet contain dedicated concepts for general relativity, compact-object astrophysics or gravitational-wave analysis.");if(/neural network|machine learning|deep learning|artificial intelligence/.test(t))gaps.push("The starter library does not yet contain dedicated concepts for statistical learning, neural-network architectures or model evaluation.");if(/quantum/.test(t))gaps.push("The starter library does not yet contain dedicated quantum mechanics or quantum information concepts.");return gaps.join(" ")}
function planForm(qid,existing){let qidValue=existing?.questionId||qid||"",q=state.questions.find(x=>x.id===qidValue),suggested=suggestedTopics(qidValue),selected=existing?.topics||suggested,caveat=coverageCaveat(qidValue);return head("KNOWLEDGE ARCHITECT",existing?"Revise your learning plan":"Construct a learning plan","A useful route should be specific, flexible and tied to something you intend to understand or make.")+'<div class="plan-intro"><div class="eyebrow">DRIVING INQUIRY</div><h3>'+esc(q?.title||"Independent learning")+'</h3><p>'+(q?"Your plan stays connected to this question.":"You can build a route without a saved inquiry.")+'</p></div>'+(existing?"":'<div class="suggestion-note"><b>Suggested starting points</b><p>'+(suggested.length?suggested.map(k=>topics[k][0]).join(" · "):"No strong match in the starter graph. Explore the field and select foundations manually.")+'</p><small>Transparent keyword matching, not AI diagnosis or a complete curriculum.</small>'+(caveat?'<p class="coverage-warning">'+caveat+'</p>':"")+'</div>')+'<form class="workspace-form" id="planForm"><input type="hidden" name="questionId" value="'+esc(qidValue)+'"><label>WHAT DO YOU NEED TO BE ABLE TO EXPLAIN OR DO?<textarea name="objective" required rows="3" placeholder="State the capability you want to develop.">'+esc(existing?.objective||"")+'</textarea></label><label>FOUNDATIONAL CONCEPTS<select name="topics" multiple size="9">'+Object.keys(topics).map(k=>'<option value="'+k+'" '+(selected.includes(k)?"selected":"")+'>'+topics[k][0]+' — '+domain(topics[k][1]).name+'</option>').join("")+'</select><small>Suggestions are preselected for new plans. Use Ctrl / Command to change the selection.</small></label><label>LEARNING APPROACH<textarea name="approach" rows="3" placeholder="Read a textbook, derive equations, reproduce a paper, build a model…">'+esc(existing?.approach||"")+'</textarea></label><label>WHAT WILL YOU CREATE OR DEMONSTRATE?<textarea name="deliverable" rows="3" placeholder="A model, annotated explanation, research review, code project, experiment…">'+esc(existing?.deliverable||"")+'</textarea></label><div class="form-actions"><button class="button primary" type="submit">'+(existing?"Save revised plan":"Create learning plan")+' →</button><a class="button secondary" href="#/'+(existing?"plan/"+existing.id:"questions")+'">Cancel</a></div></form>'}
function pathways(){return head("KNOWLEDGE ARCHITECT","Learning plans","A flexible map of what you need to learn, why it matters, and how you will use it.","<a class='button primary' href='#/questions'>Start from a question →</a>")+(state.plans.length?'<div class="plan-list">'+state.plans.slice().reverse().map(p=>'<a class="plan-card" href="#/plan/'+p.id+'"><div class="feature-meta">LEARNING PLAN · '+new Date(p.created).toLocaleDateString()+'</div><h3>'+esc(p.objective)+'</h3><p>'+esc(p.deliverable||"No final output defined.")+'</p><div class="plan-progress"><span>'+p.topics.length+' mapped concepts</span><span>'+p.topics.filter(t=>state.checks.some(c=>c.topic===t&&c.correct)).length+' with task evidence</span></div></a>').join("")+'</div>':empty("A question becomes a route","Create an inquiry first, then build a learning plan around the knowledge and capabilities it requires.","questions","Develop a question"))}
function planDetail(id){let p=state.plans.find(x=>x.id===id);if(!p)return empty("Plan not found","Return to your learning plans.","pathways","Learning plans");let q=state.questions.find(x=>x.id===p.questionId);return head("LEARNING PLAN",esc(p.objective),"A revisable route. It is a proposal, not a fixed syllabus.")+'<div class="plan-intro"><div class="eyebrow">DRIVING QUESTION</div><p>'+esc(q?.title||"Independent inquiry")+'</p><div class="eyebrow">INTENDED OUTPUT</div><p>'+esc(p.deliverable||"Not specified")+'</p></div><div class="section-row"><div><div class="eyebrow">FOUNDATIONS AND CONCEPTS</div><h2>Your knowledge route</h2></div><a class="text-link" href="#/map">View map →</a></div><div class="route-list">'+p.topics.map((k,i)=>'<div class="route-item"><span class="route-index">'+String(i+1).padStart(2,"0")+'</span><div class="route-body"><h3>'+topics[k][0]+'</h3><p>'+topics[k][2]+'</p><small>'+topicStatus(k)+'</small></div><a class="button small secondary" href="#/study/'+k+'">Study →</a></div>').join("")+(p.topics.length?"":"<p>No concepts mapped. Edit this plan to add foundations.</p>")+'</div><div class="section-row"><div><div class="eyebrow">YOUR METHOD</div><h2>How you intend to learn</h2></div></div><div class="paper-panel"><p>'+esc(p.approach||"No learning approach recorded.")+'</p><div class="form-actions"><a class="button secondary" href="#/pathways/edit/'+id+'">Edit learning plan</a><button class="button danger" data-delete-plan="'+id+'">Delete plan</button></div></div>'}
function study(id){let t=topics[id];if(!t)return empty("Concept not found","Explore the starter library.","discover","Explore fields");currentTopic=id;let history=state.checks.filter(c=>c.topic===id);return head(domain(t[1]).name.toUpperCase()+" / LEARNING STUDIO",t[0],"Build a mental model, inspect the relationship, then test what you can independently retrieve.")+'<div class="study-layout"><article class="study-main"><div class="study-section"><div class="eyebrow">01 / CORE IDEA</div><h2>What is happening?</h2><p class="study-lead">'+t[2]+'</p><p>'+t[3]+'</p></div><div class="equation-panel"><div class="eyebrow">KEY RELATIONSHIP</div><div class="equation">'+t[4]+'</div><small>Write this in your own words. Identify the variables, assumptions and limits before applying it.</small></div><div class="study-section"><div class="eyebrow">02 / INDEPENDENT RETRIEVAL</div><h2>Can you use the idea?</h2><p>'+t[5]+'</p><form id="studyCheck" class="check-form"><input name="answer" required autocomplete="off" placeholder="Work it out, then enter your answer…"><label class="confidence-label">How confident are you?<select name="confidence"><option value="1">1 · Guessing</option><option value="2">2 · Unsure</option><option value="3" selected>3 · Partly confident</option><option value="4">4 · Confident</option><option value="5">5 · Could explain it</option></select></label><button class="button primary" type="submit">Check this task →</button></form><div id="studyFeedback" aria-live="polite"></div></div><div class="study-section"><div class="eyebrow">03 / REFLECTION</div><h2>Explain it in your own words</h2><textarea id="studyReflection" rows="4" placeholder="What is the underlying idea? What assumptions matter? What still feels unclear?"></textarea><button class="button secondary" id="saveReflection">Save reflection to Field Journal</button></div></article><aside class="study-aside"><div class="side-panel"><div class="eyebrow">EVIDENCE SO FAR</div><h3>'+history.length+' task attempt(s)</h3><p>'+history.filter(c=>c.correct).length+' correct authored checks. This is narrow evidence, not proof of mastery.</p></div><div class="side-panel"><div class="eyebrow">STATED PREREQUISITES</div>'+(prereq[id]||[]).map(k=>'<a class="prereq-link" href="#/study/'+k+'">'+topics[k][0]+' →</a>').join("")||'<p>No prerequisite is currently encoded in the starter graph.</p>'+'</div><div class="side-panel"><div class="eyebrow">CONTINUE THE INQUIRY</div><a class="prereq-link" href="#/investigate/new">Open Investigation Lab →</a><a class="prereq-link" href="#/resources">Add a source →</a><a class="prereq-link" href="#/journal">Open Field Journal →</a></div></aside></div>'}
function mapPage(){let ids=Object.keys(topics);return head("KNOWLEDGE ARCHITECT","Knowledge map","Inspect the starter concept graph. Edges show authored prerequisite relationships, not every possible intellectual connection.")+'<div class="map-legend"><span><i class="legend-dot assessed"></i>Task evidence recorded</span><span><i class="legend-dot neutral"></i>Not assessed</span><span>Lines = stated prerequisite</span></div><div class="knowledge-map">'+ids.map((id,i)=>{let t=topics[id];return '<a class="map-node '+(state.checks.some(c=>c.topic===id&&c.correct)?"has-evidence":"")+'" style="--n:'+i+'" href="#/study/'+id+'"><small>'+domain(t[1]).name+'</small><b>'+t[0]+'</b><span>'+topicStatus(id)+'</span></a>'}).join("")+'</div><div class="callout-note">The current graph contains a small set of manually authored prerequisite edges. It does not yet model the full depth of any discipline. Treat missing edges as unknown, not proof that no prerequisite exists.</div><div class="section-row"><div><div class="eyebrow">EXPLICIT PREREQUISITES</div><h2>Why concepts connect</h2></div></div><div class="list-card">'+Object.keys(prereq).map(k=>'<div class="list-row"><span class="row-main"><b>'+topics[k][0]+'</b><small>Builds on '+prereq[k].map(x=>topics[x][0]).join(", ")+'</small></span><a class="text-link" href="#/study/'+k+'">Inspect →</a></div>').join("")+'</div>'}
function models(){return head("MODEL BENCH","Explore a system by changing it.","Interactive teaching models make assumptions visible. Change one variable at a time, record a prediction, then compare it with the model.")+'<div class="model-grid"><section class="model-card"><div class="feature-meta">MATHEMATICS · LINEAR MODEL</div><h3>Function explorer</h3><p>Explore how slope and intercept change a linear relationship.</p><div class="model-output" id="linearOutput">y = 2x + 1 = 7</div><label class="model-control">Slope <b id="slopeValue">2</b><input id="slope" type="range" min="-4" max="4" step=".5" value="2"></label><label class="model-control">Intercept <b id="interceptValue">1</b><input id="intercept" type="range" min="-8" max="8" step="1" value="1"></label><label class="model-control">Input x <b id="xValue">3</b><input id="modelX" type="range" min="-5" max="5" step="1" value="3"></label><svg class="model-plot" viewBox="0 0 320 180" role="img" aria-label="Linear function graph"><path d="M160 8V172M8 90H312" stroke="#65716c" stroke-width="1"/><path id="linearLine" d="M20 150L300 30" stroke="#c4a477" stroke-width="2.5" fill="none"/><circle id="linearPoint" cx="244" cy="48" r="5" fill="#91aa9a"/></svg></section><section class="model-card"><div class="feature-meta">PHYSICS · IDEAL PENDULUM</div><h3>Pendulum period</h3><p>For small oscillations, period depends on length and gravitational acceleration.</p><div class="model-output" id="pendulumOutput">T ≈ 2.01 s</div><label class="model-control">Length <b id="lengthValue">1.00 m</b><input id="modelLength" type="range" min=".2" max="2.5" step=".1" value="1"></label><label class="model-control">Gravity <b id="gravityValue">9.81 m/s²</b><input id="modelGravity" type="range" min="1" max="20" step=".1" value="9.81"></label><div class="model-note">Assumptions: small angle, negligible damping, point mass and massless string.</div></section><section class="model-card"><div class="feature-meta">ENGINEERING · OHM’S LAW</div><h3>Resistive circuit</h3><p>Explore the ideal relationship between voltage, current and resistance.</p><div class="model-output" id="ohmOutput">I = 3.00 A</div><label class="model-control">Voltage <b id="voltageValue">12 V</b><input id="modelVoltage" type="range" min="1" max="24" step=".5" value="12"></label><label class="model-control">Resistance <b id="resistanceValue">4 Ω</b><input id="modelResistance" type="range" min="1" max="20" step=".5" value="4"></label><div class="model-note">Ideal ohmic resistor at constant resistance. Real components can heat and depart from this model.</div></section><section class="model-card"><div class="feature-meta">CHEMISTRY · ATOMIC STRUCTURE</div><h3>Atomic shell explorer</h3><p>Change atomic number and inspect a simplified electron-shell count. This is not an orbital model.</p><div class="model-output" id="atomOutput">Carbon · 6 protons · 6 electrons</div><label class="model-control">Atomic number <b id="atomNumberValue">6</b><input id="atomNumber" type="range" min="1" max="20" value="6"></label><div class="model-note" id="shellOutput">Simplified shell distribution: 2, 4</div></section><section class="model-card"><div class="feature-meta">BIOLOGY · CELL STRUCTURE</div><h3>Cell structure explorer</h3><p>Select a cell component and examine its role in the larger system.</p><div class="model-output" id="cellOutput">Nucleus</div><label class="model-control">Structure<select id="cellStructure"><option value="nucleus">Nucleus</option><option value="membrane">Cell membrane</option><option value="mitochondrion">Mitochondrion</option><option value="ribosome">Ribosome</option><option value="cytoplasm">Cytoplasm</option></select></label><div class="model-note" id="cellDescription">Contains most eukaryotic DNA and helps regulate gene expression.</div></section><section class="model-card"><div class="feature-meta">COMPUTER SCIENCE · ALGORITHMS</div><h3>Insertion-sort visualiser</h3><p>Step through comparisons and moves as the sorted prefix grows.</p><div class="model-output" id="sortOutput">7 · 3 · 8 · 2 · 6 · 4 · 1 · 5</div><div class="sort-bars" id="sortBars"><span style="height:63px">7</span><span style="height:27px">3</span><span style="height:72px">8</span><span style="height:18px">2</span><span style="height:54px">6</span><span style="height:36px">4</span><span style="height:9px">1</span><span style="height:45px">5</span></div><div class="sort-actions"><button class="button secondary" id="sortStep">Next step</button><button class="button secondary" id="sortReset">Reset</button></div><div class="model-note" id="sortExplanation">Start with the first value as the sorted prefix.</div></section></section></div><section class="paper-panel model-reflection"><div class="eyebrow">PREDICTION AND OBSERVATION</div><h3>What did you expect to happen?</h3><textarea id="modelPrediction" rows="2" placeholder="Write a prediction before changing the controls."></textarea><textarea id="modelObservation" rows="3" placeholder="Record what changed, what stayed constant and why."></textarea><button class="button primary" id="saveModelNote">Save to Field Journal</button></section>'}
function investigateForm(qid){return head("INVESTIGATION LAB","Design an investigation","Turn a claim or question into something you can examine. Record what you expect before you observe.")+'<form class="workspace-form" id="investigationForm"><input type="hidden" name="questionId" value="'+esc(qid||"")+'"><label>INVESTIGATION TITLE<input name="title" required placeholder="What are you investigating?"></label><label>RESEARCH QUESTION<textarea name="question" required rows="2" placeholder="Make the question specific enough to examine."></textarea></label><label>HYPOTHESIS<textarea name="hypothesis" required rows="3" placeholder="What do you expect, and why?"></textarea></label><div class="form-grid"><label>INDEPENDENT VARIABLE<input name="independent" placeholder="What will you change?"></label><label>DEPENDENT VARIABLE<input name="dependent" placeholder="What will you measure?"></label></div><label>CONTROLS, ASSUMPTIONS OR CONFOUNDERS<textarea name="controls" rows="2" placeholder="What must remain constant? What could distort the result?"></textarea></label><button class="button primary" type="submit">Create investigation →</button></form>'}
function investigate(){return head("INVESTIGATION LAB","Test an idea, not just your memory.","Record hypotheses, methods, observations and limitations. VESPER does not claim to run experiments on your behalf.","<a class='button primary' href='#/investigate/new'>+ New investigation</a>")+(state.investigations.length?'<div class="question-grid">'+state.investigations.slice().reverse().map(x=>'<a class="question-card" href="#/investigation/'+x.id+'"><div class="feature-meta">INVESTIGATION · '+esc(x.status||"Planned")+'</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.question)+'</p><div class="question-foot"><span>'+new Date(x.created).toLocaleDateString()+'</span><span>Open record →</span></div></a>').join("")+'</div>':empty("No investigations yet","Create a hypothesis and define what evidence could support or challenge it.","investigate/new","Design an investigation"))}
function investigationDetail(id){let x=state.investigations.find(v=>v.id===id);if(!x)return empty("Investigation not found","Return to the lab.","investigate","Investigation lab");return head("INVESTIGATION RECORD",esc(x.title),"A structured record of a question, expectation, observations and interpretation.")+'<div class="detail-grid"><section class="paper-panel"><div class="eyebrow">RESEARCH QUESTION</div><p>'+esc(x.question)+'</p><div class="eyebrow">HYPOTHESIS</div><p>'+esc(x.hypothesis)+'</p><div class="eyebrow">VARIABLES</div><p>Independent: '+esc(x.independent||"Not specified")+'<br>Dependent: '+esc(x.dependent||"Not specified")+'</p><div class="eyebrow">CONTROLS AND LIMITATIONS</div><p>'+esc(x.controls||"Not recorded")+'</p><form id="observationForm" class="inline-form"><label>OBSERVATION / RESULT<textarea name="observation" rows="4" placeholder="Record what happened. Separate observation from interpretation.">'+esc(x.observation||"")+'</textarea></label><label>INTERPRETATION<textarea name="interpretation" rows="4" placeholder="Does the evidence support the hypothesis? What alternative explanations remain?">'+esc(x.interpretation||"")+'</textarea></label><label>LIMITATIONS<textarea name="limitations" rows="2" placeholder="What does this investigation not establish?">'+esc(x.limitations||"")+'</textarea></label><button class="button primary">Save investigation record</button></form></section><aside class="side-panel"><div class="eyebrow">RECORD STATUS</div><h3>'+esc(x.status||"Planned")+'</h3><p>Created '+new Date(x.created).toLocaleDateString()+'</p><button class="button secondary full" data-complete-investigation="'+id+'">Mark as reviewed</button></aside></div>'}
function workshop(){return head("CREATION WORKSHOP","Make something with what you learn.","A self-education system should lead to original work: models, papers, code, experiments and explanations.","<a class='button primary' href='#/workshop/new'>+ Create project</a>")+(state.projects.length?'<div class="question-grid">'+state.projects.slice().reverse().map(p=>'<a class="question-card" href="#/project/'+p.id+'"><div class="feature-meta">'+esc(p.kind)+' · '+esc(p.status)+'</div><h3>'+esc(p.title)+'</h3><p>'+esc(p.objective)+'</p><div class="question-foot"><span>'+new Date(p.created).toLocaleDateString()+'</span><span>Open project →</span></div></a>').join("")+'</div>':empty("Knowledge needs somewhere to go","Start a project that turns learning into a tangible output.","workshop/new","Create a project"))}
function projectForm(){return head("CREATION WORKSHOP","Define your project","Choose a concrete output and a question it will help you answer.")+'<form class="workspace-form" id="projectForm"><label>PROJECT TITLE<input name="title" required placeholder="A name that describes the work"></label><div class="form-grid"><label>OUTPUT TYPE<select name="kind"><option>Research paper</option><option>Scientific model</option><option>Software / code</option><option>Experiment</option><option>Technical explanation</option><option>Dataset analysis</option><option>Other</option></select></label><label>STATUS<select name="status"><option>Planning</option><option>In progress</option></select></label></div><label>OBJECTIVE<textarea name="objective" rows="2" required placeholder="What will this work demonstrate or investigate?"></textarea></label><label>WORKSPACE NOTES<textarea name="body" rows="5" placeholder="Outline, milestones, methods, references, draft sections…"></textarea></label><button class="button primary">Create project →</button></form>'}
function projectDetail(id){let p=state.projects.find(x=>x.id===id);if(!p)return empty("Project not found","Return to the workshop.","workshop","Creation workshop");return head("CREATION WORKSHOP",esc(p.title),"Your workbench. Keep drafts, milestones and evidence connected to the objective.")+'<form id="projectEdit" class="workspace-form"><div class="form-grid"><label>OUTPUT TYPE<select name="kind">'+["Research paper","Scientific model","Software / code","Experiment","Technical explanation","Dataset analysis","Other"].map(k=>'<option '+(p.kind===k?"selected":"")+'>'+k+'</option>').join("")+'</select></label><label>STATUS<select name="status">'+["Planning","In progress","Review","Complete"].map(k=>'<option '+(p.status===k?"selected":"")+'>'+k+'</option>').join("")+'</select></label></div><label>OBJECTIVE<textarea name="objective" rows="2">'+esc(p.objective)+'</textarea></label><label>WORKING DOCUMENT<textarea name="body" rows="14" placeholder="Write your outline, research notes, methods, code references, results and revisions here.">'+esc(p.body||"")+'</textarea></label><div class="form-actions"><button class="button primary">Save project</button><button type="button" class="button secondary" data-export-project="'+id+'">Export as Markdown</button><button type="button" class="button danger" data-delete-project="'+id+'">Delete project</button></div></form>'}
function journal(){return head("FIELD JOURNAL","Your thinking, recorded.","Keep hypotheses, questions, derivations, observations and corrections. Notes belong to you.","<a class='button primary' href='#/journal/new'>+ New entry</a>")+(state.notes.length?'<div class="journal-list">'+state.notes.slice().reverse().map(n=>'<article class="journal-entry"><div class="feature-meta">'+new Date(n.created).toLocaleString()+'</div><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p><div class="entry-actions"><button class="text-link" data-delete-note="'+n.id+'">Delete entry</button></div></article>').join("")+'</div>':empty("A place for unfinished thinking","Record a question, a derivation, a surprising result or a correction.","journal/new","Write a field note"))}
function noteForm(){return head("FIELD JOURNAL","Write a field note","Capture your thinking while it is still connected to the question or experiment.")+'<form class="workspace-form" id="noteForm"><label>ENTRY TITLE<input name="title" required placeholder="A question, observation or idea"></label><label>ENTRY<textarea name="body" rows="10" required placeholder="Write your reasoning. What do you know? What is uncertain? What evidence do you have?"></textarea></label><label>RELATED FIELD<input name="tag" placeholder="Optional subject or project"></label><button class="button primary">Save field note →</button></form>'}
function resources(){return head("RESOURCE LIBRARY","Build a trustworthy reading trail.","Save books, papers, datasets, lectures and tools. Record why each source is useful and how much confidence it deserves.","<a class='button primary' href='#/resources/new'>+ Add resource</a>")+(state.resources.length?'<div class="resource-list">'+state.resources.slice().reverse().map(r=>'<article class="resource-card"><div class="feature-meta">'+esc(r.type)+' · '+esc(r.quality||"Unreviewed")+'</div><h3>'+esc(r.title)+'</h3><p>'+esc(r.why||"No evaluation recorded.")+'</p>'+(r.url?'<a class="text-link" href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">Open source ↗</a>':"")+'<button class="text-link" data-delete-resource="'+r.id+'">Remove</button></article>').join("")+'</div>':empty("A research trail needs sources","Save useful resources and evaluate authorship, evidence, date, methods and limitations.","resources/new","Add a resource"))}
function resourceForm(){return head("RESOURCE LIBRARY","Evaluate a source","Capture bibliographic details and your own assessment. A saved link is not automatically a credible source.")+'<form class="workspace-form" id="resourceForm"><label>TITLE<input name="title" required placeholder="Paper, book, dataset, lecture or tool"></label><div class="form-grid"><label>TYPE<select name="type"><option>Research paper</option><option>Book / textbook</option><option>Dataset</option><option>Lecture / course</option><option>Documentation</option><option>Software / tool</option><option>Other</option></select></label><label>URL<input name="url" type="url" placeholder="https://…"></label></div><label>AUTHOR / ORGANISATION<input name="author" placeholder="Who produced this source?"></label><label>WHY IS IT RELEVANT?<textarea name="why" rows="2" placeholder="Which part of your question does it help address?"></textarea></label><label>QUALITY CHECK<select name="quality"><option>Unreviewed</option><option>Primary source</option><option>Peer-reviewed</option><option>Authoritative reference</option><option>Secondary explanation</option><option>Uncertain / needs checking</option></select></label><label>LIMITATIONS OR QUESTIONS<textarea name="limits" rows="2" placeholder="Check methods, date, assumptions, conflicts and missing evidence."></textarea></label><button class="button primary">Save resource →</button></form>'}
function recall(){let items=state.recall.filter(r=>!r.done);return head("KNOWLEDGE INTELLIGENCE","Recall practice","Return to ideas after time has passed. This is a learner-managed review list, not a validated memory model.")+(items.length?'<div class="list-card">'+items.map(r=>'<div class="list-row"><span class="row-main"><b>'+esc(r.title)+'</b><small>Added '+new Date(r.created).toLocaleDateString()+'</small></span><button class="button small secondary" data-recall-done="'+r.id+'">Mark reviewed</button></div>').join("")+'</div>':empty("No recall items waiting","Add a concept or question you want to retrieve later. Schedule is controlled by you.","discover","Explore concepts"))+'<div class="section-row"><div><div class="eyebrow">ADD TO YOUR RECALL QUEUE</div><h2>Choose an idea to revisit</h2></div></div><div class="topic-grid">'+Object.keys(topics).slice(0,9).map(k=>'<button class="topic-card add-recall" data-add-recall="'+k+'"><span class="feature-meta">'+domain(topics[k][1]).name.toUpperCase()+'</span><h3>'+topics[k][0]+'</h3><span>Add to queue +</span></button>').join("")+'</div>'}
function evidence(){let checks=state.checks,correct=checks.filter(c=>c.correct).length,attempted=new Set(checks.map(c=>c.topic)).size;return head("KNOWLEDGE INTELLIGENCE","Capability evidence","Review what you have attempted and produced. Activity is not mastery; one successful check is not durable understanding.")+'<div class="metric-grid"><div class="metric"><b>'+checks.length+'</b><span>Authored task attempts</span></div><div class="metric"><b>'+correct+'</b><span>Correct task checks</span></div><div class="metric"><b>'+attempted+'</b><span>Concepts attempted</span></div><div class="metric"><b>'+state.projects.length+'</b><span>Projects recorded</span></div></div><div class="callout-note">Evidence is local and incomplete. It does not establish formal attainment, expertise, transfer, or long-term retention. VESPER will show insufficient evidence rather than invent a mastery score.</div><div class="section-row"><div><div class="eyebrow">TASK-LEVEL RECORDS</div><h2>What you have attempted</h2></div></div>'+(checks.length?'<div class="list-card">'+checks.slice().reverse().map(c=>'<div class="list-row"><span class="row-main"><b>'+esc(topics[c.topic]?.[0]||c.topic)+'</b><small>'+esc(c.kind)+' · '+new Date(c.at).toLocaleString()+' · confidence '+(c.confidence||"not supplied")+'/5</small></span><span class="status-pill '+(c.correct?"positive":"neutral")+'">'+(c.correct?"CORRECT":"NOT DEMONSTRATED")+'</span></div>').join("")+'</div>':empty("No task evidence yet","Study a concept and attempt its independent check.","discover","Explore concepts"))+'<div class="section-row"><div><div class="eyebrow">ORIGINAL WORK</div><h2>Projects and investigations</h2></div></div><div class="metric-grid"><div class="metric"><b>'+state.investigations.length+'</b><span>Investigation records</span></div><div class="metric"><b>'+state.resources.length+'</b><span>Sources evaluated</span></div><div class="metric"><b>'+state.notes.length+'</b><span>Field notes</span></div><div class="metric"><b>'+state.projects.filter(p=>p.status==="Complete").length+'</b><span>Projects marked complete</span></div></div>'}
function methodPage(){let items=[["question","Form a tractable question","Move from a broad interest to a question with a defined object, scope and outcome.","questions","Develop an inquiry"],["map","Map prerequisites","Identify what must be understood first, and distinguish known foundations from missing knowledge.","map","Inspect the knowledge map"],["source","Evaluate sources","Check authorship, date, evidence, methods, citations and limitations before relying on a source.","resources/new","Evaluate a source"],["retrieve","Retrieve before rereading","Try to explain or solve from memory, then compare your reasoning with a reliable reference.","discover","Choose a concept"],["investigate","Test claims","State a hypothesis, identify variables, consider controls and record observations separately from interpretation.","investigate/new","Design an investigation"],["create","Produce an artefact","Use what you learn to build, analyse, derive, explain or publish something concrete.","workshop/new","Start a project"]];return head("SELF-EDUCATION METHOD","Learn how to learn independently.","Repeatable practices for educating yourself. Mark a method as practised only after you have used it on real work.")+'<div class="method-progress"><b>'+state.methodChecks.length+' / '+items.length+' practices marked</b><span>Self-reported practice, not an assessment.</span></div><div class="method-grid">'+items.map((x,i)=>'<article class="method-card"><div class="feature-meta">PRACTICE 0'+(i+1)+'</div><h3>'+x[1]+'</h3><p>'+x[2]+'</p><a class="text-link" href="#/'+x[3]+'">'+x[4]+' →</a><label class="practice-check"><input type="checkbox" data-method-check="'+x[0]+'" '+(state.methodChecks.includes(x[0])?"checked":"")+'><span>I have practised this in my own work</span></label></article>').join("")+'</div><div class="callout-note">The aim is not to complete this checklist. The aim is to build habits that make you less dependent on a platform, instructor or fixed curriculum.</div>'}
function settings(){return head("SYSTEM","Your environment","Control your local data and reading conditions.")+'<div class="settings-stack"><div class="setting-row"><div><b>Reduced motion</b><p>Remove non-essential transitions and motion.</p></div><button class="toggle" id="motionToggle" aria-pressed="'+state.settings.reducedMotion+'">'+(state.settings.reducedMotion?"On":"Off")+'</button></div><div class="setting-row"><div><b>Compact workspace</b><p>Reduce spacing for smaller screens and dense work.</p></div><button class="toggle" id="compactToggle" aria-pressed="'+state.settings.compact+'">'+(state.settings.compact?"On":"Off")+'</button></div><div class="setting-row"><div><b>Local-first privacy</b><p>Your questions, notes and records are stored in this browser. There is no account, cloud sync or backup.</p></div><span class="status-pill positive">ON DEVICE</span></div><div class="setting-row"><div><b>Export your work</b><p>Download all VESPER data as a JSON file.</p></div><button class="button secondary" id="exportData">Export data ↓</button></div><div class="setting-row"><div><b>Clear local data</b><p>This removes questions, plans, resources, notes and evidence from this browser.</p></div><button class="button danger" id="clearData">Clear data</button></div></div>'}
function onboarding(){return '<div class="onboard-panel"><div class="eyebrow">WELCOME TO VESPER</div><h1>Education is something<br><em>you can direct.</em></h1><p>Build your own learning routes. Investigate questions. Make things. Keep your work private on this device.</p><form id="onboardForm"><label>WHAT SHOULD WE CALL YOU? <input name="name" maxlength="30" placeholder="Optional"></label><label>WHAT ARE YOU MOST INTERESTED IN? <select name="interest"><option>Physics and space</option><option>Mathematics</option><option>Computer science and AI</option><option>Biology and life sciences</option><option>Chemistry and materials</option><option>Engineering and systems</option><option>Several fields / interdisciplinary</option><option>Still exploring</option></select></label><label>WHAT DO YOU WANT VESPER TO HELP YOU DO? <select name="goal"><option>Explore a difficult question</option><option>Build deep foundations</option><option>Conduct independent research</option><option>Build projects and models</option><option>Develop broad STEM knowledge</option><option>Learn how to learn independently</option></select></label><button class="button primary">Enter your workspace →</button></form><small>No placement test. No fixed syllabus. You can change direction at any time.</small></div>'}
function render(){let [v,a]=path();v=v||"home";let body;if(!state.onboarded&&v==="home")body=onboarding();else switch(v){case"home":body=home();break;case"questions":body=a==="new"?questionForm(editingQuestionId?state.questions.find(q=>q.id===editingQuestionId):null):questions();break;case"question":body=questionDetail(a);break;case"discover":body=discover();break;case"field":body=fieldPage(a);break;case"pathways":body=a==="new"?planForm(path()[2]):a==="edit"?planForm(null,state.plans.find(p=>p.id===path()[2])):pathways();break;case"plan":body=planDetail(a);break;case"study":body=study(a);break;case"map":body=mapPage();break;case"method":body=methodPage();break;case"investigate":body=a==="new"?investigateForm(path()[2]):investigate();break;case"models":body=models();break;case"investigation":body=investigationDetail(a);break;case"workshop":body=a==="new"?projectForm():workshop();break;case"project":body=projectDetail(a);break;case"journal":body=a==="new"?noteForm():journal();break;case"resources":body=a==="new"?resourceForm():resources();break;case"recall":body=recall();break;case"evidence":body=evidence();break;case"settings":body=settings();break;default:body=home();v="home"}state.lastView=v;$("#root").innerHTML=shell(v,body);document.body.classList.toggle("reduced-motion",!!state.settings.reducedMotion);document.body.classList.toggle("compact",!!state.settings.compact);bind(v,a)}
function toast(s){let t=$("#toast");t.textContent=s;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2300)}
function download(name,data,type){let blob=new Blob([data],{type:type||"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportData(){download("vesper-self-education-record.json",JSON.stringify({product:"VESPER",schemaVersion:1,exportedAt:now(),data:state},null,2))}
function bind(v,a){
let menu=$("#menu");if(menu)menu.onclick=()=>$("#sidebar").classList.toggle("open");
if(v==="onboard")return;
if(v==="home"&&!state.onboarded){$("#onboardForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.profile.name=f.get("name").trim();state.profile.interests=[f.get("interest")];state.profile.goal=f.get("goal");state.onboarded=true;save();go("home")};}
if(v==="questions"&&a==="new"){let editing=editingQuestionId?state.questions.find(q=>q.id===editingQuestionId):null;if(editing){$("#questionForm").elements.field.value=editing.field;$("#questionForm").elements.level.value=editing.level}$("#questionForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(editing){Object.assign(editing,{title:f.get("title").trim(),field:f.get("field"),level:f.get("level"),why:f.get("why"),known:f.get("known"),outcome:f.get("outcome")});editingQuestionId=null;save();go("question/"+editing.id)}else{let q={id:uid(),title:f.get("title").trim(),field:f.get("field"),level:f.get("level"),why:f.get("why"),known:f.get("known"),outcome:f.get("outcome"),status:"Exploring",created:now()};state.questions.push(q);save();go("question/"+q.id)}};}
if(v==="question"){$("[data-edit-question]").forEach(b=>b.onclick=()=>{editingQuestionId=b.dataset.editQuestion;go("questions/new")});$$("[data-delete-question]").forEach(b=>b.onclick=()=>{if(confirm("Delete this inquiry? Its linked plans remain in your records.")){state.questions=state.questions.filter(q=>q.id!==b.dataset.deleteQuestion);save();go("questions")}})}
if(v==="discover")$("#topicSearch").oninput=e=>{let q=e.target.value.toLowerCase();$("#topicResults").innerHTML=topicCards(Object.keys(topics).filter(k=>allText(k).includes(q)||domain(topics[k][1]).name.toLowerCase().includes(q)))};
if(v==="pathways"&&(a==="new"||a==="edit"))$("#planForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),selected=Array.from(e.target.elements.topics.selectedOptions).map(o=>o.value),id=path()[2],existing=a==="edit"?state.plans.find(x=>x.id===id):null;if(!selected.length){toast("Choose at least one concept.");return}let values={questionId:f.get("questionId"),objective:f.get("objective").trim(),topics:selected,approach:f.get("approach").trim(),deliverable:f.get("deliverable").trim()};if(existing)Object.assign(existing,values,{updated:now()});else{existing={id:uid(),...values,created:now()};state.plans.push(existing)}let q=state.questions.find(x=>x.id===values.questionId);if(q)q.status="Learning plan created";save();go("plan/"+existing.id)};
if(v==="plan")$("[data-delete-plan]").forEach(b=>b.onclick=()=>{if(confirm("Delete this learning plan? Your inquiry and evidence will remain.")){state.plans=state.plans.filter(p=>p.id!==b.dataset.deletePlan);save();go("pathways")}})
if(v==="study"){$("#studyCheck").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),ans=f.get("answer").trim().toLowerCase().replace(/\s+/g," "),t=topics[a],ok=t[6].includes(ans),confidence=+f.get("confidence");state.checks.push({id:uid(),topic:a,correct:ok,answer:ans,confidence,at:now(),kind:"Authored retrieval check"});if(ok)state.recall.push({id:uid(),title:t[0],created:now(),done:false});save();$("#studyFeedback").innerHTML='<div class="feedback '+(ok?"positive":"caution")+'"><b>'+(ok?"The authored answer matches.":"Not demonstrated on this attempt.")+'</b><p>'+esc(t[7])+'</p><small>This is evidence for one narrow task only. '+(ok?"Add a harder transfer question before treating the idea as secure.":"Review the reasoning, then try a different example.")+'</small></div>';};$("#saveReflection").onclick=()=>{let body=$("#studyReflection").value.trim();if(body){state.notes.push({id:uid(),title:"Reflection: "+topics[a][0],body,created:now(),tags:[a]});save();toast("Reflection saved to Field Journal.")}}}
if(v==="models"){let update=()=>{let m=+$("#slope").value,b=+$("#intercept").value,x=+$("#modelX").value,y=m*x+b;$("#slopeValue").textContent=m;$("#interceptValue").textContent=b;$("#xValue").textContent=x;$("#linearOutput").textContent="y = "+m+" × "+x+" + "+b+" = "+y;let x1=-5,y1=m*x1+b,x2=5,y2=m*x2+b,px=v=>160+v*27,py=v=>90-v*10;$("#linearLine").setAttribute("d","M"+px(x1)+" "+py(y1)+"L"+px(x2)+" "+py(y2));$("#linearPoint").setAttribute("cx",px(x));$("#linearPoint").setAttribute("cy",py(y))};["slope","intercept","modelX"].forEach(id=>$("#"+id).oninput=update);update();let pend=()=>{let l=+$("#modelLength").value,g=+$("#modelGravity").value;$("#lengthValue").textContent=l.toFixed(2)+" m";$("#gravityValue").textContent=g.toFixed(2)+" m/s²";$("#pendulumOutput").textContent="T ≈ "+(2*Math.PI*Math.sqrt(l/g)).toFixed(3)+" s"};["modelLength","modelGravity"].forEach(id=>$("#"+id).oninput=pend);pend();let ohm=()=>{let v=+$("#modelVoltage").value,r=+$("#modelResistance").value;$("#voltageValue").textContent=v+" V";$("#resistanceValue").textContent=r+" Ω";$("#ohmOutput").textContent="I = "+(v/r).toFixed(2)+" A"};["modelVoltage","modelResistance"].forEach(id=>$("#"+id).oninput=ohm);ohm();let elementNames=["","Hydrogen","Helium","Lithium","Beryllium","Boron","Carbon","Nitrogen","Oxygen","Fluorine","Neon","Sodium","Magnesium","Aluminium","Silicon","Phosphorus","Sulfur","Chlorine","Argon","Potassium","Calcium"];let atom=()=>{let n=+$("#atomNumber").value;$("#atomNumberValue").textContent=n;$("#atomOutput").textContent=elementNames[n]+" · "+n+" protons · "+n+" electrons";let shells=[Math.min(n,2),Math.min(Math.max(n-2,0),8),Math.max(n-10,0)].filter(x=>x>0);$("#shellOutput").textContent="Simplified shell distribution: "+shells.join(", ")+" · neutral atom assumption"};$("#atomNumber").oninput=atom;atom();let cellInfo={nucleus:"Contains most eukaryotic DNA and helps regulate gene expression.",membrane:"Selective boundary that regulates exchange with the environment.",mitochondrion:"Site of much aerobic ATP production in many eukaryotic cells.",ribosome:"Molecular machine that translates mRNA into a polypeptide.",cytoplasm:"Cell contents where many reactions occur and structures are suspended."};$("#cellStructure").onchange=()=>{$("#cellOutput").textContent=$("#cellStructure").selectedOptions[0].textContent;$("#cellDescription").textContent=cellInfo[$("#cellStructure").value]};let vals=[7,3,8,2,6,4,1,5],pass=1,j=0,key=0,phase="select";let paintSort=()=>{$("#sortOutput").textContent=vals.join(" · ");$("#sortBars").innerHTML=vals.map((v,n)=>'<span class="'+(n===j&&phase==="compare"?"current":n<pass?"sorted":"")+'" style="height:'+(v*9)+'px">'+v+'</span>').join("")};$("#sortStep").onclick=()=>{if(pass>=vals.length){$("#sortExplanation").textContent="Sorted sequence complete.";return}if(phase==="select"){key=vals[pass];j=pass-1;phase="compare";$("#sortExplanation").textContent="Hold "+key+" and compare it with the sorted prefix."}else if(j>=0&&vals[j]>key){vals[j+1]=vals[j];j--;$("#sortExplanation").textContent="Move the larger value one place right."}else{vals[j+1]=key;pass++;phase="select";$("#sortExplanation").textContent="Insert "+key+". The sorted prefix now contains "+pass+" values."}paintSort()};$("#sortReset").onclick=()=>{vals=[7,3,8,2,6,4,1,5];pass=1;j=0;key=0;phase="select";$("#sortExplanation").textContent="Start with the first value as the sorted prefix.";paintSort()};paintSort();$("#saveModelNote").onclick=()=>{let prediction=$("#modelPrediction").value.trim(),observation=$("#modelObservation").value.trim();if(!prediction&&!observation){toast("Record a prediction or observation first.");return}state.notes.push({id:uid(),title:"Model bench observation",body:"Prediction: "+(prediction||"Not recorded")+"\n\nObservation: "+(observation||"Not recorded"),created:now(),tags:["model bench"]});save();toast("Model observation saved to Field Journal.")}}
if(v==="investigate"&&a==="new")$("#investigationForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),x={id:uid(),questionId:f.get("questionId"),title:f.get("title"),question:f.get("question"),hypothesis:f.get("hypothesis"),independent:f.get("independent"),dependent:f.get("dependent"),controls:f.get("controls"),created:now(),status:"Planned"};state.investigations.push(x);save();go("investigation/"+x.id)};
if(v==="investigation"){$("#observationForm").onsubmit=e=>{e.preventDefault();let x=state.investigations.find(y=>y.id===a),f=new FormData(e.target);x.observation=f.get("observation");x.interpretation=f.get("interpretation");x.limitations=f.get("limitations");x.status="Recorded";save();toast("Investigation record saved.")};$$("[data-complete-investigation]").forEach(b=>b.onclick=()=>{let x=state.investigations.find(y=>y.id===a);x.status="Reviewed";save();render()})}
if(v==="workshop"&&a==="new")$("#projectForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),p={id:uid(),title:f.get("title"),kind:f.get("kind"),status:f.get("status"),objective:f.get("objective"),body:f.get("body"),created:now()};state.projects.push(p);save();go("project/"+p.id)};
if(v==="project"){$("#projectEdit").onsubmit=e=>{e.preventDefault();let p=state.projects.find(x=>x.id===a),f=new FormData(e.target);["kind","status","objective","body"].forEach(k=>p[k]=f.get(k));save();toast("Project saved.")};$$("[data-export-project]").forEach(b=>b.onclick=()=>{let p=state.projects.find(x=>x.id===a);download(p.title.toLowerCase().replace(/[^a-z0-9]+/g,"-")+".md","# "+p.title+"\n\n**Type:** "+p.kind+"\n**Status:** "+p.status+"\n\n## Objective\n"+p.objective+"\n\n## Working document\n"+p.body,"text/markdown")});$$("[data-delete-project]").forEach(b=>b.onclick=()=>{if(confirm("Delete this project?")){state.projects=state.projects.filter(x=>x.id!==a);save();go("workshop")}})}
if(v==="journal"&&a==="new")$("#noteForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.notes.push({id:uid(),title:f.get("title"),body:f.get("body"),created:now(),tags:[f.get("tag")]});save();go("journal")};
if(v==="journal")$$("[data-delete-note]").forEach(b=>b.onclick=()=>{state.notes=state.notes.filter(n=>n.id!==b.dataset.deleteNote);save();render()});
if(v==="resources"&&a==="new")$("#resourceForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),url=f.get("url").trim();if(url&&!/^https?:\/\//i.test(url)){toast("Use a complete http or https URL.");return}state.resources.push({id:uid(),title:f.get("title"),type:f.get("type"),url,author:f.get("author"),why:f.get("why"),quality:f.get("quality"),limits:f.get("limits"),created:now()});save();go("resources")};
if(v==="resources")$$("[data-delete-resource]").forEach(b=>b.onclick=()=>{state.resources=state.resources.filter(r=>r.id!==b.dataset.deleteResource);save();render()});
if(v==="recall"){$$("[data-add-recall]").forEach(b=>b.onclick=()=>{let k=b.dataset.addRecall;if(!state.recall.some(r=>r.title===topics[k][0]&&!r.done))state.recall.push({id:uid(),title:topics[k][0],created:now(),done:false});save();render()});$$("[data-recall-done]").forEach(b=>b.onclick=()=>{let r=state.recall.find(x=>x.id===b.dataset.recallDone);r.done=true;save();render()})}
if(v==="method")$("[data-method-check]").forEach(b=>b.onchange=()=>{let id=b.dataset.methodCheck;if(b.checked&&!state.methodChecks.includes(id))state.methodChecks.push(id);if(!b.checked)state.methodChecks=state.methodChecks.filter(x=>x!==id);save();render()});
if(v==="settings"){$("#motionToggle").onclick=()=>{state.settings.reducedMotion=!state.settings.reducedMotion;save();render()};$("#compactToggle").onclick=()=>{state.settings.compact=!state.settings.compact;save();render()};$("#exportData").onclick=exportData;$("#clearData").onclick=()=>{if(confirm("Permanently clear VESPER data stored in this browser? Export first if you need a copy.")){localStorage.removeItem(KEY);state=structuredClone(base);save();go("home")}}}
}
window.addEventListener("hashchange",render);
document.addEventListener("DOMContentLoaded",()=>{if(!location.hash)location.hash="/home";render()});
})();